Action: run_sql({'query': "WITH halal_ids AS (\n    SELECT DISTINCT gmap_id FROM establishment_attributes WHERE attribute = 'Halal food'\n    UNION\n    SELECT DISTINCT ec.gmap_id FROM establishment_categories ec JOIN category c ON ec.category_id = c.category_id WHERE lower(c.category) LIKE '%halal%'\n    UNION\n    SELECT DISTINCT gmap_id FROM establishments WHERE lower(name) LIKE '%halal%' OR lower(description) LIKE '%halal%'\n)\nSELECT \n    CASE \n        WHEN address LIKE '%Salt Lake City%' THEN 'Salt Lake City'\n        WHEN address LIKE '%West Valley City%' THEN 'West Valley City'\n        WHEN address LIKE '%Sandy%' THEN 'Sandy'\n        WHEN address LIKE '%West Jordan%' THEN 'West Jordan'\n        WHEN address LIKE '%South Jordan%' THEN 'South Jordan'\n        WHEN address LIKE '%Midvale%' THEN 'Midvale'\n        WHEN address LIKE '%Murray%' THEN 'Murray'\n        WHEN address LIKE '%Draper%' THEN 'Draper'\n        WHEN address LIKE '%Taylorsville%' THEN 'Taylorsville'\n        WHEN address LIKE '%Riverton%' THEN 'Riverton'\n        WHEN address LIKE '%Holladay%' THEN 'Holladay'\n        WHEN address LIKE '%Herriman%' THEN 'Herriman'\n        WHEN address LIKE '%South Salt Lake%' THEN 'South Salt Lake'\n        WHEN address LIKE '%Magna%' THEN 'Magna'\n        WHEN address LIKE '%Park City%' THEN 'Park City'\n        WHEN address LIKE '%Ogden%' THEN 'Ogden'\n        WHEN address LIKE '%Provo%' THEN 'Provo'\n        WHEN address LIKE '%Orem%' THEN 'Orem'\n        WHEN address LIKE '%St. George%' THEN 'St. George'\n        ELSE 'Other / Unparsed'\n    END AS city_group,\n    COUNT(*) as count\nFROM halal_ids h\nJOIN establishments e ON h.gmap_id = e.gmap_id\nGROUP BY city_group\nORDER BY count DESC;"})

