Action: run_sql({'query': "WITH halal_ids AS (\n    SELECT DISTINCT gmap_id FROM establishment_attributes WHERE attribute = 'Halal food'\n    UNION\n    SELECT DISTINCT ec.gmap_id FROM establishment_categories ec JOIN category c ON ec.category_id = c.category_id WHERE lower(c.category) LIKE '%halal%'\n    UNION\n    SELECT DISTINCT gmap_id FROM establishments WHERE lower(name) LIKE '%halal%' OR lower(description) LIKE '%halal%'\n)\nSELECT \n    c.category,\n    COUNT(DISTINCT e.gmap_id) as establishment_count\nFROM halal_ids h\nJOIN establishments e ON h.gmap_id = e.gmap_id\nJOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\nJOIN category c ON ec.category_id = c.category_id\nWHERE (\n    e.address LIKE '%Salt Lake City%' OR\n    e.address LIKE '%West Valley City%' OR\n    e.address LIKE '%Sandy%' OR\n    e.address LIKE '%West Jordan%' OR\n    e.address LIKE '%South Jordan%' OR\n    e.address LIKE '%Midvale%' OR\n    e.address LIKE '%Murray%' OR\n    e.address LIKE '%Draper%' OR\n    e.address LIKE '%Taylorsville%' OR\n    e.address LIKE '%Riverton%' OR\n    e.address LIKE '%Holladay%' OR\n    e.address LIKE '%Herriman%' OR\n    e.address LIKE '%South Salt Lake%' OR\n    e.address LIKE '%Cottonwood Heights%' OR\n    e.address LIKE '%Millcreek%' OR\n    e.address LIKE '%Magna%' OR\n    e.address LIKE '%Kearns%'\n)\nGROUP BY c.category\nORDER BY establishment_count DESC\nLIMIT 12;"})

